    "title": "摩根大通：全球人工智能交易在近期回调后有望复苏",
    "link": "https://36kr.com/newsflashes/4002992399519876?f=rss",
    "pub_date": "2026-09-28 19:57:17",
    "author": "",
    "description": "摩根大通分析师表示，近期全球AI交易的回调改善了投资者的持仓状况，也使估值变得更具吸引力，可能推动投资者重新布局，尤其是在半导体股票领域。以Mislav Matejka为首的分析师表示：“科技股可能不会回到过去那样的成功水平……但基本面仍然具有建设性，AI产业链中仍存在大量投资机会。”摩根大通还指出，持续强劲的盈利表现以及越来越多的AI商业化证据，应该能够支撑投资者重新关注这一板块。（新浪财经）",
