    "pub_date": "2026-09-28 19:48:45",
    "author": "",
    "description": "摩根士丹利的Marina Zavolock表示，债券收益率上升对股市而言“远未达到令人担忧的水平”，即使美国国债再度遭到抛售，股市仍有望保持韧性。这位摩根士丹利首席欧洲股票策略师接受采访时表示，“我知道，从市场情绪来看，当美国10年期国债收益率触及5%时，大家都有些恐慌。但我们是否已经到了预示经济衰退的水平？我建议关注欧洲高收益债券的信用利差，它们正在收窄。”（新浪财经）",
