    "content": "9月28日，孝义市2026年文旅产业高质量发展大会在山西孝义举行。高雨晴 摄 中新网吕梁9月28日电 (高雨晴)在28日举行的孝义市2026年文旅产业高质量发展大会上，山西孝义发布《孝义市奋进中国旅游百强县市三年行动计划(2026—2028)》(以下简称《行动计划》)，明确未来三年文旅产业提质升级、跻身全国百强的清晰路径。"
