    "title": "2连板吉鑫科技：拟投资不超过7亿元建设滨海风电高端装备智能制造项目",
    "link": "https://36kr.com/newsflashes/4002987427664009?f=rss",
    "pub_date": "2026-09-28 19:29:23",
    "author": "",
    "description": "36氪获悉，吉鑫科技公告，公司全资子公司吉鑫滨海拟投资建设吉鑫科技滨海风电高端装备智能制造项目(一期)，总投资不超过7亿元。项目拟新建铸造联合车间、机加工车间等设施，一期设计产能5万吨/年，建设期18个月，预计2026年11月开工。资金来源为自有资金及银行贷款。本次投资已获董事会审议通过，无需提交股东会审议。",
