    "pub_date": "2026-09-28 19:17:37",
    "author": "",
    "description": "高盛策略师称，标普500的一项市场广度指标已跌至互联网泡沫时期以来最低水平，AI行情的强势掩盖了指数整体的结构性走弱。本·斯奈德领衔的团队写道，尽管标普500距离历史高点仅相差1%，但指数成分股的中位股价较其52周高点下跌16%。他们表示：“市场广度收窄的一个潜在影响是，动量因子后续或将持续波动。”策略师同时指出，高盛的美股投资者持仓指标回落至今年3月市场低点时的水平。（新浪财经）",
