    "content": "中秋小长假后的首个交易日，A股调整有所加深。 截至9月28日收盘，上证综指跌1.67%，深证成指跌3.44%，创业板指跌4.53%。 对于市场的回调，市场各方纷纷寻找原因：如海外市场跌幅较大、10月美联储加息预期升温、美伊谈判变数加大等等。种种扰动因素下，一些投资者有所担忧甚至选择持币过节。 不过展望后市，多位受访分析人士均表示，A股短期调整不改长期韧性，认为随着中美关系新定位内涵进一步拓展，外围扰动因素的边际影响将逐渐减弱，中国资产的稳定性是资本市场确定性的坚强保障。 科技股的基本面仍在 从盘面上看，今天A股调整…"
