    "content": "雄浑的贺兰山上，文字尚未通行的漫长岁月里，远古先民用石器、金属器或矿物质颜料，留下两万余幅岩画。它们中，既有一望便知的自然物象，也有神秘抽象的文化图腾。 今年9月，宁夏银川市贺兰山岩画管理处公布了新一轮复查成果：累计新发现岩画500多幅，包括一幅罕见的“四马拉车”岩画。这些贺兰山“石头上的史书”，正从深山石壁走向更广阔大众视野，让每一个走近它的人，听见远古的回声。 石上记事 金秋时节，天高云淡，位于贺兰山东麓中段贺兰口的贺兰山岩画遗址公园内，游客络绎不绝。最具代表性的“太阳神”岩画，历经千万年光阴，依旧清晰可见。 …"
