    "description": "新华社沈阳9月28日电 题：辽宁：盐碱地变身丰收田 新华社记者武江民 清晨五点，天刚蒙蒙亮，辽宁省盘锦市盘山县胡家河蟹市场便已喧闹起来。鳞次栉比的商户门前，农妇们围坐在一起开始分拣，一掂一瞅，轻重、公母便了然于胸。不远处的稻田里，稻浪翻涌，再过半个多月就将迎来集中收割。 地处辽河三角洲中心地带的盘锦市，盐碱地分布广泛，适宜种植的粮食品种相对有限。多年来，当地联合辽宁省农业科学院盐碱地利用研究所，不仅通过培育品种，让白花花的盐碱地变成了黄…",
    "content": "新华社沈阳9月28日电 题：辽宁：盐碱地变身丰收田 新华社记者武江民 清晨五点，天刚蒙蒙亮，辽宁省盘锦市盘山县胡家河蟹市场便已喧闹起来。鳞次栉比的商户门前，农妇们围坐在一起开始分拣，一掂一瞅，轻重、公母便了然于胸。不远处的稻田里，稻浪翻涌，再过半个多月就将迎来集中收割。 地处辽河三角洲中心地带的盘锦市，盐碱地分布广泛，适宜种植的粮食品种相对有限。多年来，当地联合辽宁省农业科学院盐碱地利用研究所，不仅通过培育品种，让白花花的盐碱地变成了黄灿灿的稻田，还借助“稻蟹共养”模式，帮助农民实现增产增收。 2026年5月，辽宁…"
