    "description": "新华社北京9月28日电 中央宣传部、教育部、科技部、国家国防科工局、中央军委政治工作部、湖南省委于9月28日在北京人民大会堂联合举行“时代楷模”王戟同志先进事迹报告会。 王戟同志是国防科技大学计算机学院研究员、博士生导师，我国高可信软件技术领域主要开拓者。他长期奋战在军事教学科研一线，带领团队构建高可信软件理论框架与技术体系，研发了系列软件验证平台和检测工具，为保障多项重大装备关键软件安全可靠作出重要贡献。党的十八大以来，王戟同志自觉用…",
    "content": "新华社北京9月28日电 中央宣传部、教育部、科技部、国家国防科工局、中央军委政治工作部、湖南省委于9月28日在北京人民大会堂联合举行“时代楷模”王戟同志先进事迹报告会。 王戟同志是国防科技大学计算机学院研究员、博士生导师，我国高可信软件技术领域主要开拓者。他长期奋战在军事教学科研一线，带领团队构建高可信软件理论框架与技术体系，研发了系列软件验证平台和检测工具，为保障多项重大装备关键软件安全可靠作出重要贡献。党的十八大以来，王戟同志自觉用习近平新时代中国特色社会主义思想武装头脑，深入学习贯彻习近平强军思想，坚定不移向…"
