    "content": "新华社日本名古屋9月28日电 在刚刚结束的爱知·名古屋亚运会乒乓球女双决赛中，国乒组合蒯曼王曼昱以4:0战胜日本队组合张本美和早田希娜，获得金牌。 新华社日本名古屋9月28日电 在刚刚结束的爱知·名古屋亚运会乒乓球女双决赛中，国乒组合蒯曼/王曼昱以4:0战胜日本队组合张本美和/早田希娜，获得金牌。"
