    "title": "我国海水制氢技术有新突破",
    "link": "http://www.news.cn/20260928/c66a63346a4b4c17a09184230fa61de3/c.html",
    "pub_date": "2026-09-28 18:36:57",
    "author": "张钟仁",
    "description": "新华社济南9月28日电（记者张钟仁）9月28日，在山东日照岚山区一处中试基地，我国自研的热耦合海水制氢联产战略元素系统装置连续稳定运行超过1000小时，这一成果标志着我国成功攻克海水制氢与海洋战略元素协同联产的重大技术难题。 热耦合海水直接电解制氢，是一种无需淡化海水、直接利用工业余热降低制氢能耗的先进技术。但此前受制于两大瓶颈：一是海水电解时阴极周围碱性升高，钙、镁离子结成硬壳附在电极上，使析氢无法正常进行，最终导致催化剂失活；二是海…",
    "content": "新华社济南9月28日电（记者张钟仁）9月28日，在山东日照岚山区一处中试基地，我国自研的热耦合海水制氢联产战略元素系统装置连续稳定运行超过1000小时，这一成果标志着我国成功攻克海水制氢与海洋战略元素协同联产的重大技术难题。 热耦合海水直接电解制氢，是一种无需淡化海水、直接利用工业余热降低制氢能耗的先进技术。但此前受制于两大瓶颈：一是海水电解时阴极周围碱性升高，钙、镁离子结成硬壳附在电极上，使析氢无法正常进行，最终导致催化剂失活；二是海水中的氯离子易腐蚀电极，甚至可能析出有毒氯气。 项目负责人、中国科学院院士、崂山…"
