    "content": "记者从南京大学获悉，该校史宇坤教授与内蒙古自然博物馆以及美国霍华德大学、卡内基自然历史博物馆的科研人员合作，通过分析一件早白垩世哺乳动物化石，证实约1.25亿年前小型哺乳动物已明确具备半水生适应特征。国际学术期刊《自然·通讯》9月28日发表相关研究。 这是“板尾董尖齿兽”的化石标本。（南京大学供图） 史宇坤告诉记者，此次新发现的哺乳动物命名为“板尾董尖齿兽”，相关标本2018年发现于辽宁凌源。这种小动物体长约30厘米，其前后足具有发达的侧向扩展结构，与如今的鸭嘴兽蹼足高度相似。但“板尾董尖齿兽”的尾巴不像现代河狸和…"
