    "description": "咸阳原，自古便是关中的帝王陵寝集聚之地。自战国至西汉，一座座封土静立于此，历经风雨，不少陵寝的墓主身份已难以考证。 这是在上召窑秦陵考古发现的玉琮。（陕西省考古研究院供图） 咸阳原是位于西安市区西北方向的一片古原地带，依托厚重的历史遗存，成为城市周边独具特色的人文探访目的地。每逢节假日，不少偏爱历史人文的游客专程前来，踏访古原遗迹、触摸千年文脉。“站在古陵封土旁，能感受到这片土地千年的沧桑变化，细细体会这里沉淀下来的历史底蕴。”前来探访…",
    "content": "咸阳原，自古便是关中的帝王陵寝集聚之地。自战国至西汉，一座座封土静立于此，历经风雨，不少陵寝的墓主身份已难以考证。 这是在上召窑秦陵考古发现的玉琮。（陕西省考古研究院供图） 咸阳原是位于西安市区西北方向的一片古原地带，依托厚重的历史遗存，成为城市周边独具特色的人文探访目的地。每逢节假日，不少偏爱历史人文的游客专程前来，踏访古原遗迹、触摸千年文脉。“站在古陵封土旁，能感受到这片土地千年的沧桑变化，细细体会这里沉淀下来的历史底蕴。”前来探访的游客李建伟说。 这是游客在陕西考古博物馆参观。新华社记者 李一博 摄 2018…"
