    "content": "新华社石家庄9月28日电（记者郭雅茹）被称为“未来之城”的雄安，寄托着人们的未来观。这座新城在拔节生长中着眼于打造自主创新和原始创新重要策源地，主动“拥抱”未来产业。 一天清晨，记者来到雄安商务服务中心一家咖啡店，店里没有忙碌的咖啡师，只有一台双臂灵活的5G机器人“AI咖大师”，取豆、研磨、注水，动作流畅。接过一杯热咖啡，记者在雄安新区一场颇具未来感的体验便开始了。 前往雄安新区科创中心中试基地的路上，记者用手机约到一辆无人驾驶汽车。线上叫车、自动开门、无感起步，全程没有驾驶员；遇到十字路口、人行横道和行人，车辆会…"
