    "author": "",
    "description": "长征时期，军号是红军重要的战地指挥信号。冲锋、集合、行军等号音传递作战指令，调度部队行动。嘹亮的号声回荡在雄关险隘与雪山草地之间，既鼓舞将士斗志，凝聚战斗力量，也映照着红军不怕艰险、奋勇向前的长征精神，激励后人赓续红色血脉。",
    "content": "长征时期，军号是红军重要的战地指挥信号。冲锋、集合、行军等号音传递作战指令，调度部队行动。嘹亮的号声回荡在雄关险隘与雪山草地之间，既鼓舞将士斗志，凝聚战斗力量，也映照着红军不怕艰险、奋勇向前的长征精神，激励后人赓续红色血脉。"
