    "content": "新华社东京9月28日电 题：东京又见施廷懋 新华社记者高萌、刘艺淳、张粲 时隔五年多，施廷懋又一次出现在东京水上运动中心。 “我走进来先看到灯光，然后听见跳板的声音，又闻到池水的味道……那个瞬间我突然就感觉自己被拉回了5年前。” 2021年8月1日，就在这里，施廷懋夺得东京奥运会女子3米板单人金牌。彼时快到30岁生日的她，成为奥运会女子3米板单人项目历史上年龄最大的冠军。 “我一下就想到了自己在板上跳的时候那种感觉，一切都很熟悉。再一次来到这里，身份发生了变化。”这一次，施廷懋坐上了解说席。 解说席前，她依旧留着一…"
