    "author": "李倩薇,戴小河",
    "description": "新华社北京9月28日电（记者李倩薇、戴小河）记者28日从国家市场监督管理总局了解到，国家市场监督管理总局（国家标准委）批准发布的七项建筑材料燃烧性能试验方法推荐性国家标准已完成6个月实施过渡期，将于2026年10月1日起正式实施。 该批标准围绕GB 8624—2025《建筑材料及制品燃烧性能分级》核心分级指标，覆盖多类关键试验维度，构成完整的建筑防火材料试验评价体系。 这七项标准覆盖不燃性、可燃性、难燃性、单体燃烧、铺地材料、燃烧热值、…",
    "content": "新华社北京9月28日电（记者李倩薇、戴小河）记者28日从国家市场监督管理总局了解到，国家市场监督管理总局（国家标准委）批准发布的七项建筑材料燃烧性能试验方法推荐性国家标准已完成6个月实施过渡期，将于2026年10月1日起正式实施。 该批标准围绕GB 8624—2025《建筑材料及制品燃烧性能分级》核心分级指标，覆盖多类关键试验维度，构成完整的建筑防火材料试验评价体系。 这七项标准覆盖不燃性、可燃性、难燃性、单体燃烧、铺地材料、燃烧热值、质量损失测定等核心试验场景。其中，《建筑材料不燃性试验方法》优化试验装置、温度控…"
