    "author": "",
    "description": "",
    "content": "快科技9月28日消息， 在阿根廷首都布宜诺斯艾利斯市中心，一栋充满魔幻古堡气质的百年建筑意外走红，大量游客慕名打卡 。 之所以如此，是因为它酷似电影《哈利·波特》里出现的古灵阁巫师银行，不少网友戏称它是“宇宙第一大行的霍格沃兹分行”。 这座大楼并非工行新建，是当地受保护的历史建筑，大楼于1921年动工、1924年完工，最初是美国波士顿第一国民银行阿根廷总部 。 中国工行在2011年收购阿根廷标准银行，2013年正式入驻这栋百年大楼，成为阿根廷目前唯一的中资银行，在2022年，工行阿根廷还落地人民币清算行服务，承担当…"
