    "content": "过去一年，蔚来似乎有意在新车发布时不再过分强调「换电」的重要性。以笔者自己的体感而言，无论是新车发布会，还是线下门店里用户的讨论度，换电都不再是「最重要的那一个话题点」。 但换电退到了幕后，却没有影响蔚来的新车销量：第三代 ES8 上市 12 个月销量突破 15 万台，ES9 上市 4 个月累计交付突破 3 万台。 现在，换电这件事又有了新进展。 9 月 28 日，在中秋假期后的第一个工作日，蔚来的能源业务迎来了一个重要的合作伙伴。吉利控股将以旗下易易互联 100% 的股权，加上 6.4 亿元现金，入股蔚来能源。交…"
